import{_ as o,l as r,o as e,c as s,v as l,p as n,x as t,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"掩模雾化","description":"","frontmatter":{"title":"掩模雾化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-haze.md","filePath":"litho/mask-haze.md","lastUpdated":1789023840000}'),d={name:"litho/mask-haze.md"};function c(m,a,A,_,B,f){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="掩模雾化" tabindex="-1">掩模雾化 <a class="header-anchor" href="#掩模雾化" aria-label="Permalink to &quot;掩模雾化&quot;">​</a></h1><div class="epigraph"><p>铵盐晶体在曝光下慢慢长：昨天 AIMS 合格的版，可以在剂量累积后变成渐进缺陷。</p><footer>—— 对照 photomask haze / progressive defects 与硫酸根–铵根化学的公开文献传统</footer></div><p><a href="/litho/aims-mask-qualification">上一课</a>用打印视角放行了版。缺口是时间：DUV 高剂量曝光、残留离子、 pellicle 微环境会在膜上或石英上长雾（haze）。本课钉掩模雾化。雾化管理要进周期与钱，留给[下一课](/litho/mask-cost-cycle）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>渐进缺陷不是写入器当场写错，而是存储与曝光中成核生长：历史上典型的是硫酸根残留遇氨形成硫酸铵晶体，在 193 nm 下加速。雾斑吸收或散射，CD 缓慢漂移，检验昨天还干净。EUV 环境是真空与氢，化学不同，但仍有碳污染、锡、氢致损伤等「时间相关」掩模变化——不要把 DUV haze 化学直接抄到 EUV，只保留「渐进」这一类问题。</p><p>缺口是<strong>寿命化学</strong>，不是再做一次出货 AIMS。把 CD 漂移全写成扫描机剂量，会漏掉版在变。</p><h3 id="pellicle-是反应器也是屏障" tabindex="-1">Pellicle 是反应器也是屏障 <a class="header-anchor" href="#pellicle-是反应器也是屏障" aria-label="Permalink to &quot;Pellicle 是反应器也是屏障&quot;">​</a></h3><p>膜减少颗粒打印，却圈出一小体积气体。残留、胶挥发、框胶出气在此浓缩。无膜则与腔体气氛交换，污染物种不同。清洗课留下的离子，在这里变成可观测雾。</p><p><span class="marginnote">雾化对策是化学与物流：漂洗、存储氮气、控制氨、定期再洗或限制曝光剂量，而不是加一层 OPC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监测：周期回厂检验、晶圆上「突然」的重复缺陷图（每场相同位置）。确认是雾则清洗或报废，不能靠修复针去刮晶体了事——根在表面化学。预防：改清洗、换 pellicle 材料与胶、控制 fab 氨背景。剂量记账：高曝光层的版寿命按脉冲数管理。</p><p>与产能：关键层版若频繁下线再洗，等于掩模厂产能被 fab 曝光计划占用——成本课要算这次循环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成核需要过饱和离子与能量。193 nm 光子提供光化学路径，晶体一旦超过打印阈值就进重复缺陷。空间上常从高剂量区或残留斑开始，不像随机颗粒那样每片不同位置。这与随机颗粒的 yield 模型要分开：雾化是系统性、时间相关的。</p>',14)),(e(),n(p,null,{default:t(()=>[E(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ION%5B%22%E6%B8%85%E6%B4%97%E7%A6%BB%E5%AD%90%E6%AE%8B%E7%95%99%22%5D%20--%3E%20ENV%5B%22pellicle%20%E5%BE%AE%E6%B0%94%E6%B0%9B%20%2F%20%E6%B0%A8%22%5D%0A%20%20ENV%20--%3E%20EXP%5B%22DUV%20%E5%89%82%E9%87%8F%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20EXP%20--%3E%20HAZE%5B%22%E6%99%B6%E4%BD%93%20%2F%20%E9%9B%BE%E6%96%91%22%5D%0A%20%20HAZE%20--%3E%20REP%5B%22%E6%AF%8F%E5%9C%BA%E9%87%8D%E5%A4%8D%E7%BC%BA%E9%99%B7%22%5D%0A%20%20HAZE%20--%3E%20WASH%5B%22%E5%86%8D%E6%B8%85%E6%B4%97%E6%88%96%E6%8A%A5%E5%BA%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某一化学计量式写成唯一雾种——还有有机雾、其他盐。不编造「多少 mJ 必雾」的阈值。EUV 碳污染走真空课，本课只作对照。</p><p>后课默认：掩模在 fab 里有时间相关失效模式；下一课把写入、检验、修复、清洗、寿命收成成本与周期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雾化是渐进缺陷，出货 AIMS 不能保证寿命内干净。</li><li>DUV 经典路径与硫酸根/铵及曝光有关；pellicle 微环境会浓缩前体。</li><li>对策是清洗、气氛与剂量寿命，不是 OPC。</li><li>出处：photomask haze 文献传统；193 nm 渐进缺陷的公开讨论。</li></ul>',5))])}const P=o(d,[["render",c]]);export{D as __pageData,P as default};
